def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    danger_bids = []
    efficient_bids = []

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= DAILY_SALARY * 0.8:
                    efficient_bids.append(float(bid))
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    danger_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if tightness < 0:
        tightness = 0.0
    if tightness > 1:
        tightness = 1.0

    base = 26.0 + 18.0 * tightness

    if prev_bids:
        market = max(prev_bids)
        efficient_market = max(efficient_bids) if efficient_bids else market
    else:
        market = 45.0
        efficient_market = 45.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(base + 35.0, efficient_market + 6.0, 88.0 + 10.0 * tightness)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(base + 18.0, efficient_market + 3.0, 62.0 + 10.0 * tightness)
    else:
        if supply <= 17:
            bid = max(base + 14.0, efficient_market + 2.0, 54.0)
        elif supply >= 22:
            bid = min(base, efficient_market + 1.0 if prev_bids else base)
        else:
            bid = max(base, min(efficient_market + 1.5, 58.0))

    if danger_bids and hp > 4 and no_water_days == 0:
        bid = min(bid, max(base, max(danger_bids) + 1.0))

    if day >= 8:
        bid += 8.0
    if day >= 9:
        bid += 10.0

    reserve = 0.0
    if day <= 7:
        reserve = max(0.0, (10 - day) * 12.0)
    max_affordable = max(0.0, budget - reserve)

    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget
    elif day >= 9:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate pressure
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Estimate competition intensity: if others bid near/above salary, they likely contest heavily
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        pressure = 0.7
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        pressure = 0.45
    else:
        pressure = 0.25

    # If I'm in danger (low hp or consecutive no-water days), bid to secure water
    danger = 0.0
    if my_hp <= 2:
        danger = 1.0
    elif my_hp <= 4:
        danger = 0.7
    elif my_no_water_days >= 2:
        danger = 0.6
    else:
        danger = 0.3

    # Supply influences contest: higher supply reduces need for extreme bidding
    # Normalize supply to [0,1]
    norm_supply = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        norm_supply = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if norm_supply < 0.0:
        norm_supply = 0.0
    if norm_supply > 1.0:
        norm_supply = 1.0

    # Base target bid: around a fraction of salary, adjusted by pressure and danger
    # Use highest_prev_bid as an anchor to beat/meet likely clearing price.
    anchor = 0.55 * avg_prev_bid + 0.45 * highest_prev_bid

    # Target multiplier: more danger and more pressure => higher bid
    mult = 0.45 + 0.35 * pressure + 0.35 * danger - 0.15 * norm_supply
    if mult < 0.35:
        mult = 0.35
    if mult > 0.98:
        mult = 0.98

    target = mult * DAILY_SALARY

    # If others were already bidding very high yesterday, nudge above anchor slightly
    # to avoid losing when contest is intense.
    if pressure >= 0.7:
        target = max(target, anchor * 0.9)
    if pressure >= 1.0 and danger >= 0.7:
        target = max(target, anchor * 1.02)

    # Ensure we don't overspend: cap by budget and also avoid bidding beyond a reasonable daily cap
    # (budget cap is strict; daily cap helps preserve for later days).
    daily_cap = DAILY_SALARY * (0.95 if danger >= 0.7 else 0.75)

    bid = float(min(my_budget, daily_cap, target))

    # If budget is extremely low, still bid enough to attempt survival.
    if my_budget <= DAILY_SALARY * 0.2:
        bid = float(my_budget)

    # Final safety: non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

